}

async fn fetch_declarations(config: PathBuf, ingestion_key: Option<IngestionKey>)
    -> anyhow::Result<CliSuccess<StageAcknowledgement<DeclarationIngestionStage>>>
{
    let config = DeclarationFetcherConfig::try_from(&config)?;
    let data_config = DataConfig::from_env()?;
    let api = ParliamentApiClient::new(config.batch_size)?;
    let db = ExposedDatabase::new(&data_config.connection_string).await;
    let ingestion_key = ingestion_key.unwrap_or_default();
    let fs = ExposedDataPipeline::new_with_ingestion_key(&config.data_dir, ingestion_key.clone())?;
    DeclarationFetcherService::new(db, api, fs).fetch_declarations().await?;
    Ok(CliSuccess::new(StageAcknowledgement {
        path: std::path::absolute(config.data_dir)?.join(ingestion_key.to_string()).join("raw/declarations"),
        ingestion_key,
        stage: DeclarationIngestionStage::Fetch,
    }))
}

async fn resolve_declarations(config: PathBuf, ingestion_key: Option<IngestionKey>)
    -> anyhow::Result<CliSuccess<ResolvedDeclarations>>
{
    let ingestion_key = ingestion_key.ok_or_else(|| anyhow::anyhow!("declarations resolve requires --ingestion-key"))?;
    let config = DeclarationResolverConfig::try_from(&config)?;
    let storage = ExposedDataPipeline::open_cleaned_declarations(&config.data_dir, ingestion_key.clone())?;
    let scorer = WeldrsFunderScorer::new()?;
    let summary = DeclarationResolverService::new(storage, scorer, config.candidate_budget).resolve_declarations().await?;
